			require.Len(t, got, len(ref[planted])/2, "the other writer's file was replaced")

			names := packDirNames(t, fs)
			for _, n := range names {
				require.False(t, strings.HasPrefix(n, "tmp_"), "temporary file %s left behind", n)
			}
